-- Places added by hand from Plus Codes looked up on Google Maps (awae.csv).
-- Generated by supabase/tools/places_from_plus_codes.py; positions are the
-- centres of the codes (about 14 m). Safe to run again: a place already there
-- under the same name is left alone. Generated 2026-11-17.

-- Yaoundé: 11 places
insert into public.landmarks (city_id, name, aliases, location, kind, source)
select c.id, v.name, v.aliases,
       extensions.st_setsrid(extensions.st_makepoint(v.lng, v.lat), 4326)::extensions.geography,
       v.kind, 'manual'
from public.cities c, (values
  ('Carrefour Awae Escalier Maison Rouge', array['CAMLi Pizza', 'Carrefour Maison Rouge']::text[], 3.828562, 11.550813, 'place=locality'),
  ('Complexe Ladylanelle', array[]::text[], 3.829562, 11.552563, 'place=locality'),
  ('Tradex Awae Escalier', array[]::text[], 3.832437, 11.550938, 'amenity=fuel'),
  ('Vive Ensemble', array[]::text[], 3.836812, 11.554813, 'place=locality'),
  ('Istag Awaë Escalier', array[]::text[], 3.832812, 11.552188, 'amenity=school'),
  ('Express Union Awaé Escaliers', array[]::text[], 3.829937, 11.552563, 'amenity=bank'),
  ('Neptune Oil Awaé Escaliers', array[]::text[], 3.824687, 11.543688, 'amenity=fuel'),
  ('Eden Fashion Awae Escalier', array[]::text[], 3.832688, 11.552313, 'place=locality'),
  ('Raphaëlo Pizza Awae', array[]::text[], 3.830187, 11.551188, 'amenity=restaurant'),
  ('Awae Bilingual School', array[]::text[], 3.829437, 11.554813, 'amenity=school'),
  ('Supermarché Bella Awae Escalier', array[]::text[], 3.829562, 11.551063, 'shop=supermarket')
) as v(name, aliases, lat, lng, kind)
where c.name = 'Yaoundé'
on conflict (city_id, name) do nothing;
